def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    if v1 == 0 or v2 == 0:
        return None

    value = 100 / (v2 / v1)

    return {
        "value": value,
        "trace": {
            "license_fair_value": v1,
            "intangible_assets": v2,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
